{"results": [{"id": "FAM:SF05", "label": "Study family SF05: Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "score": 0.38, "reached_via": ["request matches the question or hypothesis of FAM:SF05 (0.20)", "request matches RQC:RQC-035 (0.35); FAM:SF05 auto_addresses_question RQC:RQC-035"], "attributes": {"observed_research_question": "Coaching pickup: H1->H2 share shift toward BEST vs AVOID", "auto_outcome_status": "rejected", "observed_hypothesis": "After suppression, teams shift volume toward the sheet BEST counter and away from AVOID.", "observed_result": "% shifted more toward BEST 51.6%; % used more AVOID 22.4%. Avg best pickup +0.0024 pp; BEST share 10.0%->10.2%. PO AVOID share within AVOID+INSUFF 13.4%->13.7% (+0.3 pp); BEST 12.9%->12.8%. RS AVOID +1.1 pp; BEST 13.1%-> [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "BEST pickup +0.24 pp is essentially zero; teams do not shift toward BEST; AVOID ticks up slightly.", "observed_sample_and_power": "n=591 triggers with BEST defined", "auto_validation_status": "same_pipeline_validation; evidence: repeat runs of the design agree", "observed_verdict": "null", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF08"}]}, {"id": "FAM:SF08", "label": "Study family SF08: Season adapter profiles (BEST-share consistency across seasons)", "score": 0.38, "reached_via": ["request matches RQC:RQC-035 (0.35); FAM:SF08 auto_addresses_question RQC:RQC-035", "FAM:SF05 auto_related_family (repeated_by_later_family) FAM:SF08"], "attributes": {"observed_research_question": "Season adapter profiles (BEST-share consistency across seasons)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams' post-trigger BEST vs AVOID mix is a stable coaching signature across seasons.", "observed_result": "Top mean BEST share: BOS 15.7% (10 dirs, win 70%), LAL 15.5%, GSW 13.8%. Bottom: HOU 2.5%, MIL 3.5%, LAC 4.1%. DEN 4.9% BEST / 70.8% INSUFF yet 62% win. ORL AVOID share 59.3%, 0% win.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No inferential test of stability vs noise; win% not identified with BEST share (IND 4.5% BEST, 71% win).", "observed_sample_and_power": "19 teams with n>=2 seasons", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-027"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-030"}, {"rel": "auto_related_family", "node": "FAM:SF05"}]}, {"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.323, "reached_via": ["request matches RQC:RQC-103 (0.27); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-103", "request matches the question or hypothesis of FAM:SF-CHT-039 (0.15)"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-010", "label": "Study family SF-APPA-010: Adversarial best-response v1: equilibrium strategy vs actual", "score": 0.252, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-010 (0.25)"], "attributes": {"observed_research_question": "Adversarial best-response v1: equilibrium strategy vs actual", "auto_outcome_status": "inconclusive", "observed_hypothesis": "The system's offensive strategy survives optimal defensive adjustment and beats what teams ran.", "observed_result": "Eq vs actual +1.16 pts/100; beats actual 127/240 (53%); vs baseline eq +8.52 pts/100; converged 159/240.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Doc verdict 'MARGINAL'; equilibrium PPP is model-implied not observed.", "observed_sample_and_power": "240 matchups", "auto_validation_status": "same_pipeline_validation; evidence: APPA-010: '240 matchups, 23,922 holdout possessions; iterative best-response to approximate nash eq'", "observed_method": "240 matchups, 23,922 holdout possessions; iterative best-response to approximate Nash equilibrium, model-scored PPP.", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-011"}]}], "n_results": 4}

